/* Great Again T funnel: quiz, sales page (video, offer reveal), order page. Generated by build_live.py: edit live/gat.js, never the theme copy. */
(function () {
  'use strict';
  var CFG = /*CFG*/{};
  var body = document.body;
  var page = body.getAttribute('data-gat') || '';
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };

  /* Events go to PostHog. Never a quiz answer, a name, an email or an address: only step numbers and choices of offer. */
  function track(name, props) {
    try { if (window.posthog && window.posthog.capture) window.posthog.capture(name, props || {}); } catch (e) {}
  }
  function store(k, v) { try { if (v === undefined) return window.localStorage.getItem(k); window.localStorage.setItem(k, v); } catch (e) { return null; } }

  track('gat_' + (page || 'page') + '_view', { info: body.getAttribute('data-info') || undefined });

  /* menu: close on a tap outside */
  var menu = $('details.menu');
  if (menu) {
    document.addEventListener('click', function (e) { if (menu.open && !menu.contains(e.target)) menu.open = false; });
  }

  /* every buy button reports where it sits */
  $$('a.cta').forEach(function (a) {
    a.addEventListener('click', function () {
      var sec = a.closest('[data-sec]');
      var pos = a.closest('.offerbar') ? 'top-bar' : a.closest('#offer') ? 'offer-under-video' : sec ? 'letter-' + sec.getAttribute('data-sec') : 'other';
      track('gat_button_click', { position: pos, revealed: body.classList.contains('revealed') });
    });
  });

  /* ---------------- quiz ---------------- */
  if (page === 'quiz') {
    var qs = CFG.quiz, cur = 0, started = false;
    var qEl = $('#question'), label = $('#progress-label'), bar = $('.progress'), fill = $('.progress span');
    $$('.answer').forEach(function (b) {
      b.addEventListener('click', function () {
        if (!started) { started = true; track('gat_quiz_start'); }
        cur++;
        track('gat_quiz_step', { step: cur });
        if (cur >= qs.length) {
          track('gat_quiz_finish');
          store('gat_quiz_done', '1');
          window.location.href = CFG.links.sales;
          return;
        }
        var hid = $('.answer[hidden]'); if (hid) hid.removeAttribute('hidden');
        qEl.textContent = qs[cur];
        label.textContent = 'Question ' + (cur + 1) + ' of ' + qs.length;
        bar.setAttribute('aria-valuenow', cur + 1);
        fill.style.width = ((cur + 1) * 100 / qs.length) + '%';
        qEl.focus({ preventScroll: true });
      });
    });
  }

  /* ---------------- sales page ---------------- */
  if (page === 'sales') {
    var reveal = function (source) {
      if (body.classList.contains('revealed')) return;
      body.classList.remove('pre'); body.classList.add('revealed');
      store('gat_revealed', '1');
      track('gat_offer_reveal', { source: source });
    };
    if (/[?&]offer=1(&|$)/.test(window.location.search)) reveal('link');

    var read = $('.read a');
    if (read) read.addEventListener('click', function () { track('gat_read_click'); });

    var player = $('#player'), box = $('#soundBox');
    var film = CFG.video;
    if (player && film && film.phone) {
      var v = document.createElement('video');
      v.setAttribute('playsinline', ''); v.setAttribute('preload', 'metadata');
      v.muted = true; v.autoplay = true; v.loop = true;
      v.poster = film.poster || '';
      v.src = (window.innerWidth >= 1024 && film.desk) ? film.desk : film.phone;
      v.setAttribute('aria-label', 'Video: Daniel Rose, founder of SixPackAbs.com');
      player.insertBefore(v, box);
      var marks = [30, 60, 120, 300, 600, 900], hit = {}, sound = false;
      var start = function () {
        if (sound) return;
        sound = true;
        v.loop = false; v.muted = false; v.controls = true;
        try { v.currentTime = 0; } catch (e) {}
        var p = v.play(); if (p && p.catch) p.catch(function () {});
        box.hidden = true;
        track('gat_video_play');
      };
      box.addEventListener('click', start);
      v.addEventListener('click', function () { if (!sound) start(); });
      v.addEventListener('timeupdate', function () {
        if (!sound) return;
        var t = v.currentTime;
        for (var i = 0; i < marks.length; i++) {
          if (t >= marks[i] && !hit[marks[i]]) { hit[marks[i]] = 1; track('gat_video_watch', { seconds: marks[i] }); }
        }
        if (CFG.revealAt > 0 && t >= CFG.revealAt) reveal('video');
      });
      v.addEventListener('ended', function () { track('gat_video_end'); reveal('video-end'); });
    } else if (box) {
      box.setAttribute('aria-hidden', 'true'); box.tabIndex = -1;   /* no film yet: the poster stands in */
    }
  }

  /* ---------------- order page ---------------- */
  if (page === 'order') {
    var main = $('main.co'), btn = $('#co-go'), agree = $('#agree'), err = $('#co-err');
    var shop = null;   /* {variant, plan} read from the live product, so the page can never charge a price it does not show */
    var option = function () { var r = $('input[name="gat-option"]:checked'); return r ? r.value : 'trial'; };
    var say = function (msg) { err.textContent = msg; err.hidden = !msg; };
    var paint = function () {
      var o = option();
      main.classList.toggle('is-trial', o === 'trial'); main.classList.toggle('is-single', o === 'single');
      $$('.opt').forEach(function (l) { l.classList.toggle('on', $('input', l).checked); });
      say('');
    };
    $$('input[name="gat-option"]').forEach(function (r) {
      r.addEventListener('change', function () { paint(); track('gat_option_select', { option: option() }); });
    });
    if (/[?&]option=single(&|$)/.test(window.location.search)) { var s1 = $('input[value="single"]'); if (s1) s1.checked = true; }
    paint();
    if (agree) agree.addEventListener('change', function () { if (agree.checked) say(''); });

    var load = fetch(CFG.product, { credentials: 'same-origin' }).then(function (r) { if (!r.ok) throw 0; return r.json(); }).then(function (p) {
      var vnt = null, plan = null;
      (p.variants || []).forEach(function (x) {
        if (vnt || !x.available || x.price !== CFG.singlePrice) return;
        vnt = x.id;
        (x.selling_plan_allocations || []).forEach(function (a) { if (a.price === CFG.trialPlanPrice) plan = a.selling_plan_id; });
      });
      shop = { variant: vnt, plan: plan };
    }).catch(function () { shop = { variant: null, plan: null }; });

    btn.addEventListener('click', function (e) {
      e.preventDefault();
      var o = option();
      if (o === 'trial' && agree && !agree.checked) {
        say('Please tick the box above to agree to the terms of the offer.');
        agree.focus();
        return;
      }
      btn.disabled = true;
      load.then(function () {
        var preview = /[?&]preview=1(&|$)/.test(window.location.search);
        if (!shop.variant || (o === 'trial' && (!shop.plan || !(CFG.trialOpen || preview)))) throw new Error('closed');
        track('gat_checkout_start', { option: o, value: o === 'trial' ? CFG.shipping / 100 : CFG.singlePrice / 100, currency: 'USD' });
        var item = { id: shop.variant, quantity: 1 };
        if (o === 'trial') item.selling_plan = shop.plan;
        var post = function (url, data) {
          return fetch(url, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, body: JSON.stringify(data || {}) })
            .then(function (r) { if (!r.ok) throw new Error('cart'); return r.json(); });
        };
        return post('/cart/clear.js').then(function () { return post('/cart/add.js', { items: [item] }); }).then(function () {
          window.location.href = '/checkout' + (o === 'trial' && CFG.discount ? '?discount=' + encodeURIComponent(CFG.discount) : '');
        });
      }).catch(function (x) {
        btn.disabled = false;
        say(x && x.message === 'closed'
          ? 'Ordering is not open yet. Please email ' + CFG.support + ' and we will let you know when it is.'
          : 'Something went wrong and your order was not placed. Please try again, or email ' + CFG.support + '.');
        track('gat_checkout_error', { option: o, reason: x && x.message === 'closed' ? 'not-open' : 'cart' });
      });
    });
  }
})();
